// Warehouse-only shared reporting workflow. Demo persistence is browser-local.
for(const order of orders){if(order.reason){if(order.status==='Exception')order.status='Out for delivery';delete order.reason;delete order.owner;delete order.decision;order.history=order.history.filter(t=>!t.includes('Delivery failed'));}}
save();
const reportTypes=['Receiving mismatch','Inventory discrepancy','Wrong / Missing item','Warehouse damage','Processing / Return receiving delay'];
const reportSeed=[{id:'WR-2001',shop:'Golden Bloom',ref:'IN-0081',type:'Receiving mismatch',description:'Stock ၁၀၀ ပို့ထားပေမယ့် Received ၉၅ ပဲပြနေပါတယ်။ Receiving record စစ်ဆေးပေးပါ။',quantity:5,outcome:'Check receiving records and correct stock if needed',status:'Submitted',owner:'Unassigned',events:[{by:'SME',text:'Report submitted · Expected 100, recorded 95'}],evidence:'Delivery receipt IN-0081',resolution:''}];
let reports;try{reports=JSON.parse(localStorage.getItem('pc-reports-v2'))||structuredClone(reportSeed)}catch{reports=structuredClone(reportSeed)}
const reportSave=()=>localStorage.setItem('pc-reports-v2',JSON.stringify(reports));const visibleReports=()=>role==='sme'?reports.filter(r=>r.shop==='Golden Bloom'):reports;const openReports=()=>visibleReports().filter(r=>r.status!=='Closed');const reportBadge=s=>`<span class="pill ${s==='Closed'?'bg-emerald-50 text-emerald-700':s==='Awaiting SME Confirmation'?'bg-blue-50 text-blue-700':'bg-orange-50 text-orange-700'}">${esc(s)}</span>`;
function reportList(){return `<div class="flex flex-wrap justify-between items-start gap-4 mb-5"><div><p class="text-sm">${role==='sme'?'My warehouse reports · မိမိတင်ထားသော Reports':'Incoming SME reports · Warehouse စစ်ဆေးဖြေရှင်းရန်'}</p><p class="text-xs muted mt-2">Warehouse-related issues only. Courier delays / failed deliveries are out of scope.</p></div>${role==='sme'?'<button class="primary" id="reportNew">＋ Report warehouse issue</button>':''}</div><div class="grid sm:grid-cols-3 gap-4 mb-5">${[['Open reports',openReports().length],['Awaiting SME Confirmation',visibleReports().filter(r=>r.status==='Awaiting SME Confirmation').length],['Closed',visibleReports().filter(r=>r.status==='Closed').length]].map(m=>`<div class="card p-5"><p class="muted text-xs">${m[0]}</p><b class="text-2xl block mt-3">${m[1]}</b></div>`).join('')}</div><div class="card overflow-auto"><table class="w-full"><thead><tr><th>Report / Reference</th><th>SME / Issue</th><th>Status</th><th>Owner</th><th></th></tr></thead><tbody>${visibleReports().map(r=>`<tr><td><b>${r.id}</b><p class="muted mt-1">${esc(r.ref)}</p></td><td>${esc(r.type)}<p class="muted mt-1">${esc(r.shop)}</p></td><td>${reportBadge(r.status)}<p class="mt-2">${typeof priorityBadge==='function'?priorityBadge(r):''}</p></td><td>${esc(r.owner)}</td><td><button class="reportView text-emerald-700 font-semibold" data-id="${r.id}">Open report ↗</button></td></tr>`).join('')||'<tr><td colspan="5" class="text-center muted">No reports yet.</td></tr>'}</tbody></table></div><div class="card p-5 mt-5"><p class="text-xs muted leading-6">Submitted → Under Review → In Progress → Awaiting SME Confirmation → Closed<br>SME Confirm လုပ်မှ Case ပိတ်ပါမည်။ No automatic closure.</p></div>`}
const baseRender=render;render=function(){baseRender();if(role==='rider'){$('#nav [data-page="Exceptions"]').remove();return}$('#nav [data-page="Exceptions"]').html(`<span class="inline-block w-7 muted">⚑</span>${role==='sme'?'My Reports':'SME Reports'}<span class="float-right text-xs bg-orange-100 text-orange-700 px-2 rounded">${openReports().length}</span>`);if(page==='Exceptions'){$('#title,#crumb').text(role==='sme'?'My warehouse reports':'SME reports');$('#subtitle').text('SME Report → Warehouse Investigation → SME Confirmation');$('#content').html(reportList())}if(page==='Overview'){let metric=$('.metric[data-page="Exceptions"]').first();metric.find('.text-3xl').html(`${openReports().length}<span class="text-xs font-normal muted ml-2">reports</span>`);metric.find('.flex.justify-between').html('Open warehouse reports <span class="text-orange-600">⚑</span>');let attention=$('#content .grid.xl\\:grid-cols-\\[1fr_320px\\]').children().last();if(!attention.length)attention=$('#content').children().last().children().last();attention.html(`<h2 class="text-sm font-semibold mb-4">Warehouse reports</h2>${openReports().map(r=>`<button class="reportView text-left w-full bg-orange-50 border border-orange-100 rounded-lg p-4 mb-3" data-id="${r.id}"><b class="text-xs">${r.id} · ${esc(r.type)}</b><p class="text-xs muted mt-2">${esc(r.status)}</p></button>`).join('')||'<p class="text-xs muted">No open reports.</p>'}${role==='sme'?'<button class="primary mt-3" id="reportNew">＋ Report warehouse issue</button>':'<p class="text-xs muted mt-3">Assign → Investigate → Propose resolution</p>'}`)}};
const baseDetail=detail;detail=function(id){baseDetail(id);$('#riderForm option').filter(function(){return $(this).text()==='Exception'}).remove();$('#modalBody .action').filter(function(){return ['retry','return','assign','resolve'].includes($(this).data('action'))}).remove();$('#modalBody').find('p').filter(function(){return $(this).text().includes('Resolution needs SME decision')}).remove();if(role==='sme')$('#modalBody').append(`<button id="reportNew" data-ref="${esc(id)}" class="primary mt-5">Report warehouse issue</button>`)};
function reportForm(ref=''){modal('Report warehouse issue',`<form id="reportForm" class="space-y-4"><div class="flex justify-end"><button type="button" id="autofillReport" class="field text-xs !w-auto">✦ Autofill demo data</button></div><div class="bg-emerald-50 p-3 rounded-lg text-xs leading-6">Warehouse-related issues only · Stock, receiving, packing, damage and processing.<br>Courier delay / failed delivery ကို ဒီ Form မှာ မတင်ပါနှင့်။</div><label class="text-xs block">Order / Shipment ID or SKU<input name="ref" class="field mt-2" value="${esc(ref)}" required maxlength="80"></label><label class="text-xs block">Issue type<select class="field mt-2" name="type">${reportTypes.map(t=>`<option>${t}</option>`).join('')}</select></label><label class="text-xs block">Description<textarea name="description" class="field mt-2" required maxlength="1500" placeholder="ဘာဖြစ်ခဲ့တာလဲ၊ စစ်ဆေးပေးရန် အသေးစိတ်ရေးပါ။"></textarea></label><label class="text-xs block">Affected quantity (optional)<input type="number" min="1" name="quantity" class="field mt-2"></label><label class="text-xs block">Requested outcome<input name="outcome" class="field mt-2" required maxlength="300"></label><label class="text-xs block">Evidence reference / description (optional)<input name="evidence" class="field mt-2" maxlength="300" placeholder="Receipt number or photo description"></label><p class="text-xs muted">Demo: text evidence only. File upload is not connected.</p><button class="primary w-full">Submit report to warehouse</button></form>`)}
function showReport(id){let r=visibleReports().find(x=>x.id===id);if(!r)return;let actions='';if(role==='warehouse'&&r.status!=='Closed'){actions=`<div class="border-t pt-5 mt-5"><h3 class="font-semibold text-sm mb-3">Warehouse actions</h3>${r.owner==='Unassigned'?`<button class="field reportAction mb-3" data-id="${id}" data-action="assign">Assign to me</button>`:''}${['Submitted','Reopened','Waiting for SME'].includes(r.status)?`<button class="field reportAction mb-3" data-id="${id}" data-action="review">Start / resume review</button>`:''}${r.status==='Under Review'?`<button class="primary reportAction mb-3" data-id="${id}" data-action="progress">Start investigation</button>`:''}${['Under Review','In Progress','Reopened'].includes(r.status)?`<form class="reportChange space-y-3" data-id="${id}"><label class="text-xs block">Next action<select name="action" class="field mt-2"><option value="information">Request more information</option>${r.status==='In Progress'?'<option value="resolution">Propose resolution</option>':''}</select></label><textarea class="field" name="note" required maxlength="1500" placeholder="Findings, evidence and action taken. For out-of-scope issues, explain the finding here."></textarea><button class="primary">Send to SME</button></form>`:''}<p class="text-xs muted mt-3">Warehouse cannot close a case. SME confirmation is required.</p></div>`}if(role==='sme'&&r.status==='Awaiting SME Confirmation')actions=`<div class="border-t pt-5 mt-5"><button class="primary reportAction w-full mb-4" data-id="${id}" data-action="close">✓ Confirm & Close</button><form class="reportChange space-y-3" data-id="${id}"><input type="hidden" name="action" value="reopen"><textarea class="field" name="note" required maxlength="1500" placeholder="မပြေလည်သေးသည့် အကြောင်းရင်းရေးပါ။"></textarea><button class="field">Reopen report</button></form></div>`;if(role==='sme'&&r.status==='Waiting for SME')actions=`<form class="reportChange space-y-3 mt-5" data-id="${id}"><input type="hidden" name="action" value="reply"><textarea class="field" name="note" required maxlength="1500" placeholder="Requested information / evidence reference"></textarea><button class="primary">Send information</button></form>`;modal(r.id+' · Warehouse report',`<div class="mb-5">${reportBadge(r.status)}</div><p class="text-sm font-semibold">${esc(r.type)}</p><p class="text-xs muted mt-2">${esc(r.shop)} · ${esc(r.ref)} · Owner: ${esc(r.owner)}</p><div class="bg-slate-50 rounded-lg p-4 my-5 text-sm whitespace-pre-wrap">${esc(r.description)}</div><div class="text-xs space-y-2 mb-5"><p>Affected quantity: ${esc(r.quantity||'Not specified')}</p><p>Requested outcome: ${esc(r.outcome)}</p><p>Evidence: ${esc(r.evidence||'Not provided')}</p></div>${r.resolution?`<div class="bg-blue-50 p-4 rounded-lg mb-5"><b class="text-xs">Latest proposed resolution</b><p class="text-sm mt-2 whitespace-pre-wrap">${esc(r.resolution)}</p></div>`:''}<h3 class="text-sm font-semibold mb-4">Shared case history</h3>${r.events.map(e=>`<div class="step text-xs"><b>${esc(e.by)}</b><p class="mt-1 whitespace-pre-wrap">${esc(e.text)}</p></div>`).join('')}${actions}`)}
function reportTransition(r,action,note=''){const warehouse=role==='warehouse',sme=role==='sme';if(action==='assign'&&warehouse&&r.status!=='Closed')r.owner='Warehouse Ops';else if(action==='review'&&warehouse&&['Submitted','Reopened','Waiting for SME'].includes(r.status)){r.status='Under Review';r.owner='Warehouse Ops'}else if(action==='progress'&&warehouse&&r.status==='Under Review')r.status='In Progress';else if(action==='information'&&warehouse&&['Under Review','In Progress','Reopened'].includes(r.status)&&note.trim())r.status='Waiting for SME';else if(action==='resolution'&&warehouse&&r.status==='In Progress'&&note.trim()){r.status='Awaiting SME Confirmation';r.resolution=note.trim()}else if(action==='close'&&sme&&r.status==='Awaiting SME Confirmation')r.status='Closed';else if(action==='reopen'&&sme&&r.status==='Awaiting SME Confirmation'&&note.trim())r.status='Reopened';else if(action==='reply'&&sme&&r.status==='Waiting for SME'&&note.trim())r.status='Under Review';else return false;r.events.push({by:warehouse?'Warehouse':'SME',text:action+' → '+r.status+(note?' · '+note.trim():'')});return true}
$(document).on('click','#reportNew',function(){reportForm($(this).data('ref')||'')});$(document).on('click','.reportView',function(){showReport($(this).data('id'))});$(document).on('submit','#reportForm',function(e){e.preventDefault();if(role!=='sme')return;let f=new FormData(this);if(!f.get('ref').trim()||!f.get('description').trim()||!f.get('outcome').trim()){note('Please complete the required fields.');return}let r={id:'WR-'+(Math.max(2000,...reports.map(r=>/^WR-\d+$/.test(r.id)?Number(r.id.slice(3)):2000))+1),shop:'Golden Bloom',ref:f.get('ref').trim(),type:f.get('type'),description:f.get('description').trim(),quantity:f.get('quantity'),products:typeof readPriorityProducts==='function'?readPriorityProducts(this):[],prioritySignals:{safetyIncident:f.get('safetyIncident')==='on',temperatureBreach:f.get('temperatureBreach')==='on'},outcome:f.get('outcome').trim(),evidence:f.get('evidence').trim(),status:'Submitted',owner:'Unassigned',resolution:'',events:[{by:'SME',text:'Report submitted'}]};reports.unshift(r);reportSave();page='Exceptions';render();showReport(r.id);note('Report submitted to warehouse')});$(document).on('click','.reportAction',function(){let r=visibleReports().find(r=>r.id===$(this).data('id'));if(r&&reportTransition(r,$(this).data('action'))){reportSave();render();showReport(r.id);note('Report updated · '+r.status)}});$(document).on('submit','.reportChange',function(e){e.preventDefault();let r=visibleReports().find(r=>r.id===$(this).data('id')),f=new FormData(this);if(r&&reportTransition(r,f.get('action'),f.get('note'))){reportSave();render();showReport(r.id);note('Report updated · '+r.status)}else note('Action requires a valid status and a written explanation.')});$('#reset').on('click',()=>{for(const o of orders){if(o.reason){o.status='Out for delivery';delete o.reason;delete o.owner;delete o.decision;o.history=o.history.filter(t=>!t.includes('Delivery failed'));}}save();reports=structuredClone(reportSeed);reportSave();render()});
$(document).on('click','#autofillReport',function(){const form=$('#reportForm');if(!form.length)return;const data={ref:form.find('[name="ref"]').val().trim()||'IN-0081',type:'Receiving mismatch',description:'Linen shirt ၁၀၀ ထည် ပို့ထားပေမယ့် Warehouse received စာရင်းမှာ ၉၅ ထည်သာ ပြနေပါတယ်။ Delivery receipt နဲ့ Receiving record ကို တိုက်စစ်ပေးပါ။',quantity:5,outcome:'Receiving records စစ်ဆေးပြီး အရေအတွက်ကွာဟမှုကို ရှင်းပြပေးရန်၊ လိုအပ်ပါက Stock စာရင်းပြင်ဆင်ပေးရန်။',evidence:'Demo receipt IN-0081 · Expected 100 units / Recorded 95 units'};Object.entries(data).forEach(([name,value])=>form.find('[name="'+name+'"]').val(value));note('Sample data ဖြည့်ပြီးပါပြီ။ Review လုပ်ပြီး Submit နှိပ်ပါ။');});

render();
